    """Reconstruct a message from a Serializable constructor envelope.

    Handles dicts in the format produced by `langchain_core.load.dumpd`:
    `{"lc": 1, "type": "constructor", "id": [..., "<ClassName>"], "kwargs": {...}}`.

    The class name is read from the last element of `id` and mapped to the
    corresponding message type. Chunk variants (e.g. `HumanMessageChunk`) are
    reconstructed as their parent (non-chunk) message type.

    Args:
        message: The serialized constructor envelope.

    Returns:
        The reconstructed message.

    Raises:
        ValueError: If the class name is unknown or unsupported.
    """
    kwargs = message["kwargs"]
    class_name = message["id"][-1]

    if class_name in {"HumanMessage", "HumanMessageChunk"}:
        return HumanMessage(**kwargs)
    if class_name in {"AIMessage", "AIMessageChunk"}:
        # Passing `kwargs` through directly preserves `tool_calls` exactly.
        return AIMessage(**kwargs)
    if class_name in {"SystemMessage", "SystemMessageChunk"}:
        return SystemMessage(content=kwargs.get("content", ""))
    if class_name in {"ToolMessage", "ToolMessageChunk"}:
        additional_kwargs = kwargs.get("additional_kwargs") or {}
        tool_kwargs: dict[str, Any] = {
            "content": kwargs.get("content", ""),
            "tool_call_id": kwargs.get("tool_call_id"),
        }
        if kwargs.get("status") is not None:
            tool_kwargs["status"] = kwargs["status"]
        if "artifact" in additional_kwargs:
            tool_kwargs["artifact"] = additional_kwargs["artifact"]
        return ToolMessage(**tool_kwargs)
    if class_name in {"FunctionMessage", "FunctionMessageChunk"}:
        return FunctionMessage(
            content=kwargs.get("content", ""),
            name=kwargs.get("name"),
        )

    msg = f"Unable to reconstruct message from envelope; unknown class {class_name!r}."
    msg = create_message(message=msg, error_code=ErrorCode.MESSAGE_COERCION_FAILURE)
    raise ValueError(msg)


